'use strict';

// Finds the "Generated by Claude Code" footer that the cloud GitHub route appends to a post after it
// leaves the session, and says how to remove it. The footer is added server side, so the before-tool
// attribution guard cannot see it; this module reads what GitHub sent back instead.
//
// - `footerDecision` is the after-tool (PostToolUse) check. In a governed or guarded checkout, a GitHub
//   write whose returned body ends with the footer gets a block decision naming the clean edit for kinds
//   the cloud can edit cleanly (issue and pull request comments, issue and pull request bodies), and a
//   note for review comments and review bodies, which only the device sweep can clean. Reads only the
//   hook input: no git, gh or network call.
// - `stripFooter` and `hasFooter` are shared with the device sweep (toolkit-github-footer-sweep.cjs).

const fs = require('node:fs');
const path = require('node:path');
const { githubWrite } = require('../../skills/github-program-reconciler/scripts/programme-refresh-trigger.cjs');

// A rule line, then the italic footer, as the last lines of the body. Tolerates CRLF, extra blank
// lines, surrounding spaces and a session path after /code. Matched line by line, so no regular
// expression backtracks over the whole body.
const FOOTER_LINE = /^[ \t]*_Generated by \[Claude Code\]\(https:\/\/claude\.ai\/code[^)\s]*\)_[ \t]*$/;
const RULE_LINE = /^[ \t]*-{3,}[ \t]*$/;
const MAX_BODY = 1024 * 1024;

// The lines before the footer's rule line, or null when the body does not end with the footer.
function linesBeforeFooter(body) {
  if (typeof body !== 'string' || body.length > MAX_BODY) return null;
  const lines = body.split('\n').map((line) => line.replace(/\r$/, ''));
  let at = lines.length - 1;
  const skipBlank = () => { while (at >= 0 && !lines[at].trim()) at -= 1; };
  skipBlank();
  if (at < 0 || !FOOTER_LINE.test(lines[at])) return null;
  at -= 1;
  skipBlank();
  if (at < 0 || !RULE_LINE.test(lines[at])) return null;
  at -= 1;
  skipBlank();
  return lines.slice(0, at + 1);
}

function hasFooter(body) { return linesBeforeFooter(body) !== null; }
function stripFooter(body) {
  const kept = linesBeforeFooter(body);
  return kept === null ? body : kept.join(body.includes('\r\n') ? '\r\n' : '\n');
}

const MAX_DEPTH = 6;
const MAX_TEXT = 2 * 1024 * 1024;

function parseJson(text) {
  if (typeof text !== 'string' || text.length > MAX_TEXT) return undefined;
  const trimmed = text.trim();
  if (!/^[[{]/.test(trimmed)) return undefined;
  try { return JSON.parse(trimmed); } catch { return undefined; }
}

// Every object in a tool response that carries a string body, with JSON text (MCP content blocks,
// shell stdout, one object per line) parsed on the way.
function postedObjects(value, found = [], depth = 0) {
  if (depth > MAX_DEPTH || value === null || value === undefined) return found;
  if (typeof value === 'string') {
    const parsed = parseJson(value);
    if (parsed !== undefined) return postedObjects(parsed, found, depth + 1);
    if (value.length <= MAX_TEXT && value.includes('\n{')) {
      for (const line of value.split(/\r?\n/)) {
        const item = parseJson(line);
        if (item !== undefined) postedObjects(item, found, depth + 1);
      }
    }
    return found;
  }
  if (Array.isArray(value)) {
    for (const item of value.slice(0, 200)) postedObjects(item, found, depth + 1);
    return found;
  }
  if (typeof value === 'object') {
    if (typeof value.body === 'string') found.push(value);
    for (const [key, item] of Object.entries(value)) {
      if (key !== 'body') postedObjects(item, found, depth + 1);
    }
  }
  return found;
}

// What a posted object is, from its html_url, else from the tool that wrote it.
const TOOL_KINDS = {
  add_issue_comment: 'issue_comment', update_issue_comment: 'issue_comment',
  create_pull_request: 'pull_request', update_pull_request: 'pull_request',
  issue_write: 'issue', create_issue: 'issue', update_issue: 'issue',
  add_reply_to_pull_request_comment: 'review_comment', add_comment_to_pending_review: 'review_comment',
  pull_request_review_write: 'review', create_and_submit_pull_request_review: 'review', submit_pending_pull_request_review: 'review',
};

function describe(object, toolKind, input) {
  const url = typeof object.html_url === 'string' ? object.html_url : (typeof object.url === 'string' ? object.url : '');
  const match = /^https:\/\/github\.com\/([\w.-]+)\/([\w.-]+)\/(issues|pull)\/(\d+)(?:#(issuecomment|discussion_r|pullrequestreview)-?(\d+))?\/?$/.exec(url);
  const target = { url: url || null, repository: null, number: null, id: null, kind: toolKind || null };
  if (match) {
    target.repository = `${match[1]}/${match[2]}`;
    target.number = Number(match[4]);
    target.id = match[6] ? Number(match[6]) : null;
    target.kind = match[5] === 'issuecomment' ? 'issue_comment'
      : match[5] === 'discussion_r' ? 'review_comment'
        : match[5] === 'pullrequestreview' ? 'review'
          : match[3] === 'pull' ? 'pull_request' : 'issue';
  }
  const { owner, repo } = input?.tool_input || {};
  if (!target.repository && typeof owner === 'string' && typeof repo === 'string' && owner && repo) target.repository = `${owner}/${repo}`;
  if (target.id === null && (target.kind === 'issue_comment' || target.kind === 'review_comment' || target.kind === 'review') && Number.isInteger(object.id)) target.id = object.id;
  if (target.number === null && Number.isInteger(object.number)) target.number = object.number;
  return target;
}

const CLEAN_KINDS = new Set(['issue_comment', 'pull_request', 'issue']);
const EDIT_TOOLS = new Set(['update_issue_comment', 'update_pull_request', 'update_issue']);

function cleanEdit(target) {
  const [owner, repo] = String(target.repository || 'OWNER/REPO').split('/');
  const where = `owner ${owner}, repo ${repo}`;
  if (target.kind === 'issue_comment') return `GitHub connector \`update_issue_comment\` (${where}, comment_id ${target.id ?? '?'})`;
  if (target.kind === 'pull_request') return `GitHub connector \`update_pull_request\` (${where}, pullNumber ${target.number ?? '?'})`;
  return `GitHub connector \`issue_write\` with method update (${where}, issue_number ${target.number ?? '?'})`;
}

const label = (target) => target.url || `${target.kind} in ${target.repository || 'this repository'}`;

// The checkout at or above a folder, when it is governed or guarded: the programme binding, the
// personal-data guard config, or the governed rules block in AGENTS.md.
function guardedCheckout(folder) {
  if (typeof folder !== 'string' || !folder) return false;
  let current = path.resolve(folder);
  for (let depth = 0; depth < 64; depth += 1) {
    if (fs.existsSync(path.join(current, '.git'))) {
      if (fs.existsSync(path.join(current, '.github', 'toolkit-programme.json'))) return true;
      if (fs.existsSync(path.join(current, '.github', 'personal-data-guard.json'))) return true;
      try {
        const agents = path.join(current, 'AGENTS.md');
        if (fs.statSync(agents).size <= 1024 * 1024 && /BEGIN TOOLKIT-GOVERNED-RULES\b/.test(fs.readFileSync(agents, 'utf8'))) return true;
      } catch { /* no AGENTS.md */ }
      return false;
    }
    const up = path.dirname(current);
    if (up === current) return false;
    current = up;
  }
  return false;
}

const SWEEP = 'node repo/scripts/toolkit-github-footer-sweep.cjs --repo <owner/name> --apply';

// The after-tool decision: {} when there is nothing to do, else a Claude Code PostToolUse output.
function footerDecision(input, deps = {}) {
  if (!input || typeof input !== 'object' || input.hook_event_name !== 'PostToolUse') return {};
  if (!githubWrite(input)) return {};
  const guarded = deps.guarded || guardedCheckout;
  if (!guarded(input.cwd)) return {};
  const tool = /^mcp__.+__([^_].*)$/.exec(String(input.tool_name || ''))?.[1] || '';
  const toolKind = TOOL_KINDS[tool] || null;
  const response = input.tool_response;
  const objects = postedObjects(response);
  const footed = objects.filter((object) => hasFooter(object.body)).map((object) => describe(object, toolKind, input));
  const unique = [...new Map(footed.map((target) => [label(target), target])).values()];
  // An edit that came back with the footer again would only loop; leave it to the device sweep.
  const edit = EDIT_TOOLS.has(tool) || (tool === 'issue_write' && input.tool_input?.method === 'update');
  const strippable = edit ? [] : unique.filter((target) => CLEAN_KINDS.has(target.kind));
  const deviceOnly = edit ? unique : unique.filter((target) => !CLEAN_KINDS.has(target.kind));
  if (strippable.length) {
    const steps = strippable.map((target) => `- ${label(target)}: call ${cleanEdit(target)} with the same body minus the "Generated by Claude Code" footer, then read it back.`);
    const extra = deviceOnly.length ? ` Review comments and reviews cannot be cleaned from the cloud; list them in your report for the device sweep (\`${SWEEP}\`): ${deviceOnly.map(label).join(', ')}.` : '';
    return { decision: 'block', reason: `GitHub added the "Generated by Claude Code" footer to what you just posted. Toolkit rules forbid it. Remove it now:\n${steps.join('\n')}${extra}` };
  }
  if (deviceOnly.length) {
    return { hookSpecificOutput: { hookEventName: 'PostToolUse', additionalContext: `GitHub added the "Generated by Claude Code" footer to ${deviceOnly.map(label).join(', ')}. Review comments and reviews cannot be cleaned from the cloud: list them in your report; the device sweep (\`${SWEEP}\`) cleans them.` } };
  }
  // A cloud write whose response shows no body cannot be checked here: ask for a read-back.
  const cloud = (deps.env || process.env).CLAUDE_CODE_REMOTE === 'true';
  if (cloud && toolKind && objects.length === 0 && /^mcp__/.test(String(input.tool_name || ''))) {
    return { hookSpecificOutput: { hookEventName: 'PostToolUse', additionalContext: 'The cloud GitHub route may have added a "Generated by Claude Code" footer to this post, and the response does not show the body. Read it back; if the footer is there, remove it with the matching update call (update_issue_comment, update_pull_request or issue_write), or list a review comment for the device sweep.' } };
  }
  return {};
}

module.exports = Object.freeze({ hasFooter, stripFooter, postedObjects, describe, guardedCheckout, footerDecision, SWEEP });
